<!DOCTYPE html>
<html lang="en" id="top">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="description" content="Dune Line — the overnight train from the Al Qamar dunes to the neon of Miraj City. Linen berths, a glass dome full of stars, dinner over the salt flats.">
<meta name="theme-color" content="#0b0817">
<title>Dune Line — Overnight train from the dunes to the neon</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%230b0817'/%3E%3Ccircle cx='16' cy='13' r='6' fill='%23f0b46a'/%3E%3Cpath d='M3 20Q10 14 16 19T29 19' stroke='%23f0b46a' stroke-width='1.8' fill='none'/%3E%3Cpath d='M4 27H28' stroke='%23ff5fa8' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E">
<style>
/* ============================================================
   DUNE LINE — design tokens
   ============================================================ */
:root{
  --bg0:#0b0817;
  --bg1:#120e26;
  --panel:#161130;
  --panel2:#100c22;
  --ink:#f4ecdf;
  --muted:#a99cc4;
  --faint:#7a6da3;
  --sand:#f0b46a;
  --sand-hi:#ffd9a0;
  --coral:#ef8354;
  --rose:#ff5fa8;
  --magenta:#ff4fd8;
  --cyan:#5ff2e0;
  --cyan-soft:#8ff2e6;
  --line:rgba(240,190,120,.15);
  --line-soft:rgba(244,236,223,.08);
  --accent-grad:linear-gradient(90deg,#f0b46a,#ff5fa8,#5ff2e0);
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,"Times New Roman",serif;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --mono:ui-monospace,"SF Mono","Cascadia Code",Menlo,Consolas,"Liberation Mono",monospace;
  --scene-h:clamp(230px,33vw,460px);
  --radius:20px;
  --nav-h:72px;
}

/* ============================================================
   Reset & base
   ============================================================ */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  background:var(--bg0);
  color:var(--ink);
  font-family:var(--sans);
  font-size:16px;
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
  overflow-x:hidden;
}
::selection{background:var(--rose);color:#1a0a20}
::-webkit-scrollbar{width:10px}
::-webkit-scrollbar-track{background:var(--bg0)}
::-webkit-scrollbar-thumb{background:#2b2152;border-radius:6px;border:2px solid var(--bg0)}
::-webkit-scrollbar-thumb:hover{background:#3a2d6e}
img,svg{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
ul{list-style:none}
:focus-visible{outline:2px solid var(--sand);outline-offset:3px;border-radius:4px}
[id]{scroll-margin-top:calc(var(--nav-h) + 24px)}

.container{max-width:1180px;margin-inline:auto;padding-inline:24px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip-link{position:fixed;top:-60px;left:16px;z-index:200;background:var(--sand);color:#2b1508;padding:10px 16px;border-radius:8px;font-weight:600;transition:top .2s}
.skip-link:focus{top:12px}

/* film grain over everything, drawn in code */
.grain{position:fixed;inset:0;width:100%;height:100%;z-index:90;pointer-events:none;opacity:.05;mix-blend-mode:overlay}

/* scroll progress — the route completing */
.progress{position:fixed;top:0;left:0;right:0;height:2px;z-index:95;background:var(--accent-grad);transform-origin:0 50%;transform:scaleX(0)}

/* ============================================================
   Type helpers
   ============================================================ */
.mono{font-family:var(--mono)}
.eyebrow{
  display:flex;align-items:center;gap:12px;
  font-family:var(--mono);font-size:11px;letter-spacing:.24em;text-transform:uppercase;
  color:var(--sand);
}
.eyebrow::before{content:"";width:26px;height:2px;border-radius:2px;background:var(--accent-grad);flex:none}
.eyebrow .no{color:var(--faint)}
h1,h2,h3{font-family:var(--serif);font-weight:600;letter-spacing:-.015em;line-height:1.08}
.sec-head h2{font-size:clamp(30px,3.6vw,44px);margin-top:16px}
.sec-head .sub{color:var(--muted);max-width:560px;margin-top:14px;font-size:16px}
.sec{padding:110px 0}
.sec-head{margin-bottom:56px}
.sec-head-row{display:flex;align-items:flex-end;justify-content:space-between;gap:32px;flex-wrap:wrap}

.neon-text{
  font-style:italic;
  color:var(--rose);
  background:linear-gradient(100deg,#f0b46a 0%,#ff5fa8 48%,#5ff2e0 105%);
  -webkit-background-clip:text;background-clip:text;
  -webkit-text-fill-color:transparent;
}

/* ============================================================
   Buttons & segmented control
   ============================================================ */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;
  padding:15px 24px;border-radius:12px;
  font-weight:600;font-size:15px;line-height:1;letter-spacing:.01em;
  transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease,background-color .22s ease;
  white-space:nowrap;
}
.btn .arr{transition:transform .22s ease;font-family:var(--mono)}
.btn:hover .arr{transform:translateX(4px)}
.btn-primary{
  background:linear-gradient(135deg,#f6c179,#ef8354);
  color:#2b1508;
  box-shadow:0 6px 24px -8px rgba(240,160,90,.45);
}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 12px 32px -8px rgba(240,160,90,.6)}
.btn-ghost{border:1px solid var(--line);color:var(--ink);background:rgba(240,190,120,.03)}
.btn-ghost:hover{transform:translateY(-2px);border-color:rgba(240,180,106,.5);background:rgba(240,190,120,.07)}
.btn-neon{
  background:linear-gradient(135deg,#ff5fa8,#c44ff0);
  color:#fff5fb;
  box-shadow:0 6px 26px -8px rgba(255,95,168,.5);
}
.btn-neon:hover{transform:translateY(-2px);box-shadow:0 12px 34px -8px rgba(255,95,168,.65)}
.btn-sm{padding:11px 18px;font-size:13.5px;border-radius:10px}
.btn-block{width:100%}

.seg{display:inline-flex;gap:4px;padding:4px;background:var(--panel2);border:1px solid var(--line-soft);border-radius:11px}
.seg button{
  font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--muted);padding:9px 14px;border-radius:8px;transition:color .2s,background .2s,box-shadow .2s;
}
.seg button:hover{color:var(--ink)}
.seg button[aria-pressed="true"]{
  color:var(--sand-hi);
  background:linear-gradient(135deg,rgba(240,180,106,.16),rgba(255,95,168,.13));
  box-shadow:inset 0 0 0 1px rgba(240,180,106,.35);
}

/* pulse dot */
.dot{width:8px;height:8px;border-radius:50%;flex:none;display:inline-block}
.dot-amber{background:var(--sand);box-shadow:0 0 10px rgba(240,180,106,.9);animation:pulse 2.2s ease-in-out infinite}
.dot-cyan{background:var(--cyan);box-shadow:0 0 10px rgba(95,242,224,.8)}
.dot-mute{background:#5a4d85}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(240,180,106,.55)}55%{box-shadow:0 0 0 7px rgba(240,180,106,0)}}

/* ============================================================
   Navigation
   ============================================================ */
.nav{
  position:fixed;top:0;left:0;right:0;z-index:70;height:var(--nav-h);
  background:rgba(11,8,23,.55);
  -webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);
  border-bottom:1px solid transparent;
  transition:background .3s,border-color .3s;
}
.nav.scrolled{background:rgba(11,8,23,.88);border-bottom-color:var(--line-soft)}
.nav-inner{height:var(--nav-h);display:flex;align-items:center;justify-content:space-between;gap:24px}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{width:34px;height:34px;flex:none}
.brand-name{font-weight:700;font-size:13px;letter-spacing:.26em}
.brand-tag{font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--faint);margin-top:3px}
.nav-links{display:flex;align-items:center;gap:30px}
.nav-links a{font-size:14px;font-weight:500;color:var(--muted);position:relative;padding:6px 0;transition:color .2s}
.nav-links a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:1.5px;background:var(--accent-grad);border-radius:2px;transform:scaleX(0);transform-origin:0 50%;transition:transform .25s ease}
.nav-links a:hover{color:var(--ink)}
.nav-links a:hover::after,.nav-links a[aria-current="true"]::after{transform:scaleX(1)}
.nav-links a[aria-current="true"]{color:var(--sand-hi)}
.nav-cta{display:flex;align-items:center;gap:14px}
.burger{display:none;width:42px;height:42px;border:1px solid var(--line-soft);border-radius:10px;position:relative}
.burger span{position:absolute;left:11px;right:11px;height:2px;background:var(--ink);border-radius:2px;transition:transform .25s,top .25s,opacity .25s}
.burger span:nth-child(1){top:15px}
.burger span:nth-child(2){top:24px}
.nav.open .burger span:nth-child(1){top:19px;transform:rotate(45deg)}
.nav.open .burger span:nth-child(2){top:19px;transform:rotate(-45deg)}
.m-menu{display:none;position:absolute;top:var(--nav-h);left:0;right:0;background:rgba(11,8,23,.97);border-bottom:1px solid var(--line-soft);padding:14px 24px 22px}
.nav.open .m-menu{display:block;animation:menuIn .25s ease}
@keyframes menuIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
.m-menu a{display:block;padding:13px 0;font-size:16px;color:var(--muted);border-bottom:1px solid var(--line-soft)}
.m-menu a:hover{color:var(--ink)}
.m-menu .btn{margin-top:16px}

/* ============================================================
   Hero
   ============================================================ */
.hero{
  position:relative;
  min-height:min(100svh,980px);
  padding:calc(var(--nav-h) + 60px) 0 calc(var(--scene-h) - 118px);
  background:linear-gradient(180deg,#0b0817 0%,#140e2e calc(100% - var(--scene-h)),#201347 calc(100% - var(--scene-h)));
  overflow:hidden;
}
/* CSS star field above the SVG scene */
.hero::before{
  content:"";position:absolute;left:0;right:0;top:0;height:62%;pointer-events:none;opacity:.65;
  background-image:
    radial-gradient(1.4px 1.4px at 8% 24%,rgba(255,244,224,.9) 50%,transparent 51%),
    radial-gradient(1px 1px at 19% 58%,rgba(210,216,255,.8) 50%,transparent 51%),
    radial-gradient(1.6px 1.6px at 27% 18%,rgba(255,244,224,.85) 50%,transparent 51%),
    radial-gradient(1px 1px at 36% 44%,rgba(210,216,255,.7) 50%,transparent 51%),
    radial-gradient(1.3px 1.3px at 47% 12%,rgba(255,244,224,.8) 50%,transparent 51%),
    radial-gradient(1px 1px at 55% 36%,rgba(255,214,240,.7) 50%,transparent 51%),
    radial-gradient(1.5px 1.5px at 64% 20%,rgba(210,216,255,.85) 50%,transparent 51%),
    radial-gradient(1px 1px at 72% 50%,rgba(255,244,224,.65) 50%,transparent 51%),
    radial-gradient(1.4px 1.4px at 81% 15%,rgba(190,246,255,.8) 50%,transparent 51%),
    radial-gradient(1px 1px at 90% 40%,rgba(255,214,240,.75) 50%,transparent 51%),
    radial-gradient(1.2px 1.2px at 95% 22%,rgba(255,244,224,.7) 50%,transparent 51%),
    radial-gradient(1px 1px at 13% 76%,rgba(210,216,255,.5) 50%,transparent 51%),
    radial-gradient(1px 1px at 43% 66%,rgba(255,244,224,.45) 50%,transparent 51%),
    radial-gradient(1px 1px at 78% 72%,rgba(190,246,255,.45) 50%,transparent 51%);
  -webkit-mask-image:linear-gradient(180deg,#000 55%,transparent);mask-image:linear-gradient(180deg,#000 55%,transparent);
  animation:skyTwinkle 7s ease-in-out infinite alternate;
}
@keyframes skyTwinkle{from{opacity:.45}to{opacity:.75}}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:64px;align-items:center}
.hero-eyebrow{display:inline-flex;align-items:center;gap:10px;font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--sand);border:1px solid rgba(240,180,106,.28);background:rgba(240,180,106,.05);padding:8px 14px;border-radius:999px}
.hero h1{font-size:clamp(42px,5.2vw,64px);margin-top:22px;line-height:1.04}
.hero-sub{color:var(--muted);font-size:17px;max-width:540px;margin-top:20px}
.hero-ctas{display:flex;gap:14px;margin-top:26px;flex-wrap:wrap}
.hero-status{display:flex;align-items:center;gap:10px;margin-top:20px;font-family:var(--mono);font-size:11.5px;letter-spacing:.16em;color:var(--muted)}
.hero-status b{color:var(--sand-hi);font-weight:600}

/* entrance */
.hero-in{animation:fadeUp .9s cubic-bezier(.2,.7,.2,1) both}
.hero-in.d1{animation-delay:.08s}.hero-in.d2{animation-delay:.18s}.hero-in.d3{animation-delay:.3s}.hero-in.d4{animation-delay:.42s}.hero-in.d5{animation-delay:.54s}
@keyframes fadeUp{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}

/* Boarding pass */
.ticket-wrap{justify-self:end;animation:floaty 7s ease-in-out infinite}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.ticket{
  position:relative;width:330px;
  background:linear-gradient(165deg,#1c1440,#131028 70%);
  border:1px solid rgba(240,190,120,.22);
  border-radius:18px;padding:22px 24px 20px;
  transform:rotate(2.4deg);
  box-shadow:0 30px 60px -20px rgba(0,0,0,.65),0 0 0 1px rgba(0,0,0,.3);
  transition:transform .35s ease,box-shadow .35s ease;
}
.ticket:hover{transform:rotate(0deg) translateY(-4px);box-shadow:0 40px 70px -20px rgba(0,0,0,.7),0 0 40px -12px rgba(255,95,168,.25)}
.ticket-top{display:flex;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:9.5px;letter-spacing:.24em;color:var(--sand)}
.ticket-top .tl{display:flex;align-items:center;gap:8px}
.ticket-top svg{width:20px;height:20px}
.ticket-top .tr{color:var(--faint)}
.ticket-route{display:flex;align-items:center;justify-content:space-between;margin-top:20px}
.ticket-port .code{font-family:var(--mono);font-size:30px;font-weight:700;letter-spacing:.04em;color:var(--ink)}
.ticket-port .city{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--faint);margin-top:4px;text-transform:uppercase}
.ticket-port.arr .code{color:var(--cyan-soft)}
.ticket-port.arr{text-align:right}
.ticket-route .t-arrow{color:var(--rose);opacity:.85}
.ticket-meta{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:20px}
.ticket-meta .k{font-family:var(--mono);font-size:8.5px;letter-spacing:.18em;color:var(--faint)}
.ticket-meta .v{font-family:var(--mono);font-size:13px;color:var(--sand-hi);margin-top:3px;font-weight:600}
.perf{position:relative;border-top:2px dashed rgba(244,236,223,.2);margin:20px -24px 16px}
.perf::before,.perf::after{content:"";position:absolute;top:-10px;width:18px;height:18px;border-radius:50%;background:#171034;border:1px solid rgba(240,190,120,.22)}
.perf::before{left:-10px;clip-path:inset(0 0 0 50%)}
.perf::after{right:-10px;clip-path:inset(0 50% 0 0)}
.barcode{height:34px;border-radius:3px;opacity:.85;
  background:repeating-linear-gradient(90deg,#efe3cf 0 2px,transparent 2px 4px,#efe3cf 4px 7px,transparent 7px 9px,#efe3cf 9px 10px,transparent 10px 15px,#efe3cf 15px 16px,transparent 16px 19px);
}
.ticket-serial{font-family:var(--mono);font-size:8.5px;letter-spacing:.34em;color:var(--faint);text-align:center;margin-top:9px}
.stamp{position:absolute;top:-24px;right:-18px;width:96px;height:96px;transform:rotate(-12deg);opacity:.6;pointer-events:none}

/* the panorama */
.scene{position:absolute;left:0;right:0;bottom:0;height:var(--scene-h);z-index:1;pointer-events:none}
.scene svg{width:100%;height:100%}

/* scene life */
.tw{animation:twinkle 4s ease-in-out infinite alternate}
.tw2{animation-duration:5.6s;animation-delay:1.2s}
.tw3{animation-duration:3.2s;animation-delay:.6s}
@keyframes twinkle{from{opacity:.35}to{opacity:1}}
.drift{animation:drift 30s ease-in-out infinite alternate}
.drift2{animation:drift 24s ease-in-out infinite alternate-reverse}
@keyframes drift{from{transform:translateX(-26px)}to{transform:translateX(26px)}}
.blink{animation:blink 2.4s steps(1) infinite}
.blink.b2{animation-delay:1.1s;animation-duration:3.1s}
@keyframes blink{0%,72%{opacity:1}73%,80%{opacity:.15}81%,100%{opacity:1}}
.neon-flicker{animation:neonFlick 7s linear infinite}
@keyframes neonFlick{0%,18%,22%,26%,54%,100%{opacity:1}19%,21%{opacity:.3}23%,25%{opacity:.55}55%,56%{opacity:.5}57%{opacity:1}}
.wf{animation:winFlick 5s steps(1) infinite}
.wf.w2{animation-delay:2.3s;animation-duration:7s}
@keyframes winFlick{0%,88%{opacity:.9}89%,93%{opacity:.25}94%,100%{opacity:.9}}
.train{animation:ride 42s linear infinite}
@keyframes ride{from{transform:translateX(-900px)}to{transform:translateX(1500px)}}
.train-bob{animation:bob 1.5s ease-in-out infinite alternate}
@keyframes bob{from{transform:translateY(0)}to{transform:translateY(1.1px)}}
.wheel{transform-box:fill-box;transform-origin:center;animation:spin .85s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

/* ============================================================
   Marquee
   ============================================================ */
.mq{overflow:hidden;background:#0a0716;border-block:1px solid var(--line-soft);padding:15px 0;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);
  mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);
}
.mq-track{display:flex;gap:56px;width:max-content;animation:mq 32s linear infinite}
.mq:hover .mq-track{animation-play-state:paused}
.mq-list{display:flex;gap:56px;align-items:center}
.mq-list span{font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:#b7a8d6;white-space:nowrap;display:flex;align-items:center;gap:56px}
.mq-list span::after{content:"✦";color:var(--sand);opacity:.75;font-size:9px}
@keyframes mq{to{transform:translateX(calc(-50% - 28px))}}

/* ============================================================
   Features
   ============================================================ */
#journey{position:relative;background:
  radial-gradient(700px 420px at 8% 0%,rgba(240,160,90,.06),transparent 65%),
  var(--bg0);}
.features{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.card{
  position:relative;overflow:hidden;
  background:linear-gradient(180deg,var(--panel),var(--panel2));
  border:1px solid var(--line-soft);border-radius:var(--radius);
  padding:32px 30px 26px;
  transition:transform .3s ease,border-color .3s ease,box-shadow .3s ease;
}
.card::before{content:"";position:absolute;top:0;left:0;height:2px;width:46px;background:var(--acc,var(--accent-grad));transition:width .45s ease;border-radius:0 2px 2px 0}
.card:hover{transform:translateY(-5px);border-color:rgba(240,190,120,.3);box-shadow:0 24px 50px -22px rgba(0,0,0,.7)}
.card:hover::before{width:100%}
.card .no{font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--faint)}
.card .icon{
  width:54px;height:54px;border-radius:14px;margin:20px 0 22px;
  display:grid;place-items:center;color:var(--ic,var(--sand));
  background:rgba(240,180,106,.06);border:1px solid rgba(240,180,106,.18);
  transition:box-shadow .3s ease;
}
.card:hover .icon{box-shadow:0 0 26px -6px var(--ic,var(--sand))}
.card h3{font-size:24px;margin-bottom:12px}
.card p{color:var(--muted);font-size:14.5px;line-height:1.7}
.card .foot{margin-top:24px;padding-top:16px;border-top:1px solid var(--line-soft);font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;color:var(--faint)}
.card.c-sand{--ic:#f0b46a;--acc:linear-gradient(90deg,#f6c179,#ef8354)}
.card.c-rose{--ic:#ff7ac8;--acc:linear-gradient(90deg,#ff5fa8,#c44ff0)}
.card.c-rose .icon{background:rgba(255,95,168,.06);border-color:rgba(255,95,168,.2)}
.card.c-cyan{--ic:#5ff2e0;--acc:linear-gradient(90deg,#5ff2e0,#4fb8ff)}
.card.c-cyan .icon{background:rgba(95,242,224,.05);border-color:rgba(95,242,224,.18)}

/* ============================================================
   Timetable
   ============================================================ */
#timetable{background:linear-gradient(180deg,var(--bg0),#0d0a1c 30%,var(--bg0))}
.board{
  background:linear-gradient(180deg,#151030,#0f0b20);
  border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;
  box-shadow:0 30px 70px -30px rgba(0,0,0,.8);
}
.board-top{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:18px 26px;border-bottom:1px solid var(--line-soft);background:rgba(0,0,0,.22)}
.board-title{display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--muted)}
.clock{font-family:var(--mono);font-size:12px;letter-spacing:.12em;color:var(--sand-hi);background:#0d0a1e;border:1px solid var(--line-soft);padding:7px 12px;border-radius:8px}
.clock small{color:var(--faint);letter-spacing:.2em;margin-right:8px;font-size:9px}
.tt-head,.tt-row{display:grid;grid-template-columns:170px minmax(0,1fr) 96px 116px 128px;gap:18px;align-items:center;padding:20px 26px}
.tt-head{padding:12px 26px;font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;color:var(--faint);border-bottom:1px solid var(--line-soft);background:rgba(0,0,0,.14)}
.tt-row{border-bottom:1px solid var(--line-soft);transition:background .25s}
.tt-row:last-of-type{border-bottom:0}
.tt-row:hover{background:rgba(240,180,106,.045)}
.tt-row.hide{display:none}
.tt-code{display:inline-block;font-family:var(--mono);font-size:11.5px;font-weight:700;letter-spacing:.1em;color:var(--sand);border:1px solid rgba(240,180,106,.3);border-radius:6px;padding:3px 8px;background:rgba(240,180,106,.05)}
.tt-name{display:block;font-size:14.5px;font-weight:600;margin-top:8px}
.tt-bound{display:block;font-family:var(--mono);font-size:8.5px;letter-spacing:.2em;color:var(--faint);margin-top:3px}
.tt-times{display:flex;align-items:center;gap:18px;min-width:0}
.tt-city{display:block;font-family:var(--mono);font-size:8.5px;letter-spacing:.2em;color:var(--faint);text-transform:uppercase;margin-bottom:6px}
.flap{
  position:relative;display:inline-block;font-family:var(--mono);font-size:21px;font-weight:600;letter-spacing:.06em;
  padding:6px 11px;border-radius:6px;background:#0d0a1e;border:1px solid rgba(255,255,255,.06);
  color:var(--sand-hi);
}
.flap::after{content:"";position:absolute;left:2px;right:2px;top:50%;height:1px;background:rgba(0,0,0,.6)}
.flap.arr{color:var(--cyan-soft)}
.tt-arrow{color:#4d4176;flex:none}
.tt-dur,.tt-days{font-family:var(--mono);font-size:12.5px;color:var(--muted);letter-spacing:.06em}
.tt-lab{display:none;font-family:var(--mono);font-size:8.5px;letter-spacing:.2em;color:var(--faint);margin-right:8px}
.tt-status{display:flex;align-items:center;gap:9px;font-family:var(--mono);font-size:10.5px;letter-spacing:.18em}
.st-on{color:var(--cyan)}
.st-board{color:var(--sand)}
.st-sched{color:var(--faint)}
.board-foot{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:14px 26px;font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--faint);background:rgba(0,0,0,.22);border-top:1px solid var(--line-soft)}
.board-foot b{color:var(--muted);font-weight:600}

/* ============================================================
   Fares
   ============================================================ */
#fares{position:relative;background:
  radial-gradient(760px 460px at 92% 12%,rgba(255,79,216,.055),transparent 65%),
  radial-gradient(600px 400px at 4% 88%,rgba(95,242,224,.04),transparent 65%),
  var(--bg0);}
.tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
.tier{
  position:relative;display:flex;flex-direction:column;
  background:linear-gradient(180deg,var(--panel),var(--panel2));
  border:1px solid var(--line-soft);border-radius:var(--radius);padding:34px 30px 30px;
  transition:transform .3s ease,box-shadow .3s ease,border-color .3s ease;
}
.tier:hover{transform:translateY(-5px);border-color:rgba(240,190,120,.3);box-shadow:0 26px 55px -24px rgba(0,0,0,.75)}
.tier.pop{
  border:1px solid transparent;
  background:linear-gradient(180deg,#1a1338,#120e28) padding-box,
             linear-gradient(150deg,#f0b46a,#ff5fa8 55%,#5ff2e0) border-box;
  transform:translateY(-12px);
  box-shadow:0 30px 70px -26px rgba(255,95,168,.28);
}
.tier.pop:hover{transform:translateY(-17px);box-shadow:0 38px 80px -26px rgba(255,95,168,.4)}
.pop-badge{
  position:absolute;top:-13px;left:50%;transform:translateX(-50%);
  font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.26em;
  background:linear-gradient(90deg,#f0b46a,#ff5fa8);color:#2b1020;
  padding:7px 14px;border-radius:999px;white-space:nowrap;
  box-shadow:0 6px 18px -6px rgba(255,95,168,.6);
}
.tier-kind{font-family:var(--mono);font-size:10px;letter-spacing:.26em;color:var(--tc,var(--sand))}
.tier h3{font-size:27px;margin-top:12px}
.tier .desc{color:var(--muted);font-size:13.5px;margin-top:8px;min-height:42px}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:24px}
.price-from{font-family:var(--mono);font-size:9px;letter-spacing:.22em;color:var(--faint);align-self:flex-start;margin-top:12px}
.price{font-family:var(--serif);font-size:54px;font-weight:600;letter-spacing:-.02em;line-height:1}
.price-per{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;color:var(--faint)}
.price-note{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--faint);margin-top:10px}
.tier hr{border:0;border-top:1px solid var(--line-soft);margin:24px 0 20px}
.tier ul{display:grid;gap:11px;margin-bottom:28px}
.tier li{display:flex;gap:11px;font-size:14px;color:#cfc3e4;line-height:1.5}
.tier li::before{content:"✦";color:var(--tc,var(--sand));font-size:11px;line-height:1.9;flex:none}
.tier .btn{margin-top:auto}
.tier.t-sand{--tc:#f0b46a}
.tier.t-rose{--tc:#ff7ac8}
.tier.t-cyan{--tc:#5ff2e0}
.fares-note{text-align:center;margin-top:44px;font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--faint)}

/* ============================================================
   Testimonial
   ============================================================ */
#letters{position:relative;background:
  radial-gradient(680px 420px at 82% 30%,rgba(255,79,216,.07),transparent 65%),
  radial-gradient(560px 380px at 12% 75%,rgba(95,242,224,.05),transparent 65%),
  #0d0a1c;
  border-block:1px solid var(--line-soft);
}
.quote-wrap{position:relative;max-width:840px;margin-inline:auto;text-align:center;padding-top:26px}
.quote-mark{
  position:absolute;top:-78px;left:50%;transform:translateX(-50%);
  font-family:var(--serif);font-size:230px;line-height:1;pointer-events:none;
  background:var(--accent-grad);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
  opacity:.22;
}
.stars{display:flex;justify-content:center;gap:5px;color:var(--sand);margin-bottom:28px}
.stars svg{width:15px;height:15px}
blockquote p{font-family:var(--serif);font-size:clamp(22px,2.6vw,31px);line-height:1.45;letter-spacing:-.01em;color:var(--ink)}
blockquote p em{color:var(--sand-hi);font-style:italic}
.quote-who{display:flex;align-items:center;justify-content:center;gap:16px;margin-top:36px;flex-wrap:wrap}
.avatar{width:52px;height:52px;flex:none}
.who-txt{text-align:left}
.who-txt .name{font-weight:600;font-size:15px}
.who-txt .role{color:var(--muted);font-size:13px;margin-top:2px}
.who-chip{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;color:var(--cyan);border:1px solid rgba(95,242,224,.25);background:rgba(95,242,224,.04);padding:8px 13px;border-radius:999px}
.quote-rating{margin-top:26px;font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--faint)}

/* ============================================================
   CTA band
   ============================================================ */
.cta-band{padding:110px 0}
.cta-panel{
  position:relative;overflow:hidden;text-align:center;
  border:1px solid var(--line);border-radius:26px;
  padding:60px 48px 56px;
  background:
    radial-gradient(560px 300px at 15% 110%,rgba(240,160,90,.12),transparent 65%),
    radial-gradient(560px 300px at 85% 110%,rgba(255,79,216,.12),transparent 65%),
    linear-gradient(180deg,#171134,#100c22);
}
.route-line{display:flex;align-items:center;gap:18px;max-width:620px;margin:0 auto 44px;color:var(--sand)}
.route-line .rl-city{color:var(--cyan)}
.rl-track{position:relative;flex:1;height:2px;background:repeating-linear-gradient(90deg,rgba(240,180,106,.45) 0 10px,transparent 10px 18px)}
.rl-dot{position:absolute;top:-4px;left:0;width:10px;height:10px;border-radius:50%;
  background:linear-gradient(135deg,#f0b46a,#ff5fa8);
  box-shadow:0 0 14px rgba(255,95,168,.9);
  animation:routeRun 11s linear infinite;
}
@keyframes routeRun{0%{left:0;background:linear-gradient(135deg,#f0b46a,#ef8354)}55%{background:linear-gradient(135deg,#ff5fa8,#c44ff0)}100%{left:calc(100% - 10px);background:linear-gradient(135deg,#5ff2e0,#4fb8ff)}}
.cta-panel h2{font-size:clamp(28px,3.4vw,42px);max-width:640px;margin-inline:auto}
.cta-panel .sub{color:var(--muted);margin:16px auto 30px;max-width:460px}
.cta-count{margin-top:22px;font-family:var(--mono);font-size:10.5px;letter-spacing:.24em;color:var(--faint)}
.cta-count b{color:var(--sand-hi);font-weight:600}

/* ============================================================
   Footer
   ============================================================ */
footer{position:relative;background:#080613;padding:76px 0 34px}
footer::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:var(--accent-grad);opacity:.8}
.foot-grid{display:grid;grid-template-columns:1.5fr .8fr 1fr 1.1fr;gap:52px}
.foot-brand .brand{margin-bottom:18px}
.foot-brand p{color:var(--muted);font-size:14px;max-width:300px}
.foot-route-chip{display:inline-block;margin-top:20px;font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;color:var(--sand);border:1px solid rgba(240,180,106,.25);padding:8px 13px;border-radius:999px}
.foot-h{font-family:var(--mono);font-size:10px;letter-spacing:.26em;color:var(--faint);margin-bottom:22px;text-transform:uppercase}
.foot-links li{margin-bottom:12px}
.foot-links a{color:var(--muted);font-size:14px;transition:color .2s}
.foot-links a:hover{color:var(--sand-hi)}
/* stations as a vertical route map */
.route-map{position:relative;padding-left:2px}
.route-map::before{content:"";position:absolute;left:7px;top:10px;bottom:16px;width:1.5px;background:linear-gradient(180deg,var(--sand),var(--rose),var(--cyan));opacity:.5}
.route-map li{position:relative;padding-left:28px;margin-bottom:18px}
.route-map li::before{content:"";position:absolute;left:2px;top:5px;width:9px;height:9px;border-radius:50%;background:#080613;border:2px solid var(--faint)}
.route-map li.term::before{border-color:var(--sand);background:var(--sand);box-shadow:0 0 10px rgba(240,180,106,.8)}
.route-map li.term:last-child::before{border-color:var(--cyan);background:var(--cyan);box-shadow:0 0 10px rgba(95,242,224,.8)}
.route-map .st{font-size:14px;font-weight:600}
.route-map .pf{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--faint);margin-top:2px}
.foot-desk p{color:var(--muted);font-size:14px;margin-bottom:12px}
.foot-desk a{color:var(--sand-hi)}
.foot-desk a:hover{text-decoration:underline;text-underline-offset:3px}
.foot-desk .tiny{font-size:12.5px;color:var(--faint)}
.foot-bottom{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:64px;padding-top:26px;border-top:1px solid var(--line-soft);font-family:var(--mono);font-size:9.5px;letter-spacing:.16em;color:var(--faint)}
.foot-bottom nav{display:flex;gap:22px;flex-wrap:wrap}
.foot-bottom a{color:var(--faint);transition:color .2s}
.foot-bottom a:hover{color:var(--sand-hi)}

/* ============================================================
   Reveal on scroll
   ============================================================ */
.reveal{opacity:0;transform:translateY(26px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.reveal.in{opacity:1;transform:none}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width:1024px){
  .hero-grid{grid-template-columns:minmax(0,1fr) 320px;gap:40px}
  .tt-head,.tt-row{grid-template-columns:150px minmax(0,1fr) 84px 96px 112px;gap:14px;padding-inline:20px}
}
@media (max-width:920px){
  .nav-links,.nav-cta .btn{display:none}
  .burger{display:block}
  .hero{padding-top:calc(var(--nav-h) + 44px)}
  .hero-grid{grid-template-columns:1fr;gap:0}
  .ticket-wrap{justify-self:center;margin-top:52px}
  .ticket{transform:rotate(1.6deg)}
  .features,.tiers{grid-template-columns:1fr;max-width:540px;margin-inline:auto}
  .tier.pop{transform:none}
  .tier.pop:hover{transform:translateY(-5px)}
  .sec{padding:84px 0}
  .sec-head{margin-bottom:44px}
  .foot-grid{grid-template-columns:1fr 1fr;gap:44px}
}
@media (max-width:780px){
  .tt-head{display:none}
  .tt-row{grid-template-columns:1fr auto;grid-template-areas:"svc status" "times times" "meta meta";gap:16px;padding:22px 20px}
  .tt-service{grid-area:svc}
  .tt-status{grid-area:status;justify-self:end}
  .tt-times{grid-area:times;justify-content:space-between}
  .tt-dur{grid-area:meta;display:inline-flex;align-items:center}
  .tt-days{grid-area:meta;justify-self:end;display:inline-flex;align-items:center}
  .tt-lab{display:inline}
  .tt-name{display:inline;margin:0 0 0 10px}
  .tt-bound{display:inline;margin-left:10px}
  .flap{font-size:19px}
  .board-top,.board-foot{padding-inline:20px}
  .cta-panel{padding:48px 26px 44px}
}
@media (max-width:600px){
  .foot-grid{grid-template-columns:1fr;gap:40px}
  .hero h1{font-size:clamp(38px,10.5vw,46px)}
  .hero-sub{font-size:15.5px}
  .hero-ctas .btn{flex:1;justify-content:center}
  .ticket{width:min(330px,100%)}
  .quote-mark{font-size:160px;top:-52px}
  .sec-head-row{flex-direction:column;align-items:flex-start}
  .foot-bottom{flex-direction:column;align-items:flex-start}
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important}
  .train{animation:none;transform:translateX(430px)}
  .reveal{opacity:1;transform:none}
  .mq-track{animation:none}
  .rl-dot{left:55%}
}
</style>
</head>
<body>

<a class="skip-link" href="#main">Skip to content</a>

<!-- shared SVG defs / symbols (referenced document-wide) -->
