  <defs>
    <radialGradient id="logoSunG" cx="50%" cy="35%" r="70%">
      <stop offset="0%" stop-color="#ffe4b0"/><stop offset="100%" stop-color="#ef8354"/>
    </radialGradient>
    <linearGradient id="accentG" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#f0b46a"/><stop offset="50%" stop-color="#ff5fa8"/><stop offset="100%" stop-color="#5ff2e0"/>
    </linearGradient>
    <symbol id="i-logo" viewBox="0 0 32 32">
