      <path d="M12.5 7V3.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>
      <circle cx="12.5" cy="2.6" r="1.2" fill="currentColor"/>
    </symbol>
  </defs>
</svg>

<!-- film grain -->
<svg class="grain" aria-hidden="true" preserveAspectRatio="none">
  <filter id="grainF"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" stitchTiles="stitch"/></filter>
  <rect width="100%" height="100%" filter="url(#grainF)"/>
</svg>

<div class="progress" aria-hidden="true"></div>

<!-- ============================ NAV ============================ -->
<header class="nav" id="nav">
  <div class="container nav-inner">
    <a class="brand" href="#top" aria-label="Dune Line — home">
      <svg class="brand-mark" aria-hidden="true"><use href="#i-logo"/></svg>
      <span>
        <span class="brand-name">DUNE&nbsp;LINE</span>
        <span class="brand-tag">ALQ&nbsp;⟶&nbsp;MJX&nbsp;·&nbsp;NIGHTLY</span>
      </span>
    </a>
    <nav class="nav-links" aria-label="Primary">
      <a href="#journey">The Journey</a>
      <a href="#timetable">Departures</a>
      <a href="#fares">Fares</a>
      <a href="#letters">Night Letters</a>
    </nav>
