      <a class="btn btn-primary btn-sm" href="#fares">Book a berth <span class="arr">→</span></a>
      <button class="burger" id="burger" aria-expanded="false" aria-controls="mMenu" aria-label="Toggle menu">
        <span></span><span></span>
      </button>
    </div>
  </div>
  <nav class="m-menu" id="mMenu" aria-label="Mobile">
    <a href="#journey">The Journey</a>
    <a href="#timetable">Departures</a>
    <a href="#fares">Fares</a>
    <a href="#letters">Night Letters</a>
    <a class="btn btn-primary btn-block" href="#fares">Book a berth <span class="arr">→</span></a>
  </nav>
</header>

<main id="main">

<!-- ============================ HERO ============================ -->
<section class="hero" aria-label="Dune Line — overnight express">
  <div class="container hero-grid">
    <div>
      <p class="hero-eyebrow hero-in d1"><span class="dot dot-amber"></span>PLATFORM 9 · AL QAMAR · DEPARTS 23:05</p>
      <h1 class="hero-in d2">Fall asleep<br>in the dunes.<br><em class="neon-text">Wake up in neon.</em></h1>
      <p class="hero-sub hero-in d3">An overnight train across 1,142&nbsp;km of silence — linen berths, a dome full of stars, dinner over the salt flats — until the desert breaks into a skyline of pink fire.</p>
      <div class="hero-ctas hero-in d4">
        <a class="btn btn-primary" href="#fares">Reserve a berth <span class="arr">→</span></a>
        <a class="btn btn-ghost" href="#timetable">See the night board</a>
      </div>
      <p class="hero-status hero-in d5"><span class="dot dot-amber"></span>NEXT 23:05 · BOARDING IN <b data-countdown>00H 00M 00S</b></p>
    </div>

    <div class="ticket-wrap hero-in d3">
      <div class="ticket" aria-label="Sample boarding pass">
        <svg class="stamp" viewBox="0 0 96 96" aria-hidden="true">
          <defs><path id="stampArc" d="M48,14 a34,34 0 1,1 -0.01,0"/></defs>
          <circle cx="48" cy="48" r="44" fill="none" stroke="#ff7ac8" stroke-width="1.6"/>
          <circle cx="48" cy="48" r="25" fill="none" stroke="#ff7ac8" stroke-width="1" stroke-dasharray="3 4"/>
          <text font-family="ui-monospace,Menlo,Consolas,monospace" font-size="8" letter-spacing="2.1" fill="#ff7ac8">
            <textPath href="#stampArc">DUNE LINE • NIGHT EXPRESS •</textPath>
          </text>
          <text x="48" y="47" text-anchor="middle" font-family="ui-monospace,Menlo,Consolas,monospace" font-size="11" font-weight="700" fill="#ff7ac8">23:05</text>
          <text x="48" y="59" text-anchor="middle" font-family="ui-monospace,Menlo,Consolas,monospace" font-size="5.5" letter-spacing="1.5" fill="#ff7ac8">PLATFORM 9</text>
        </svg>
        <div class="ticket-top">
          <span class="tl"><svg aria-hidden="true"><use href="#i-logo"/></svg>DUNE LINE</span>
          <span class="tr">BOARDING PASS</span>
        </div>
        <div class="ticket-route">
          <div class="ticket-port">
            <div class="code">ALQ</div>
            <div class="city">Al Qamar</div>
          </div>
          <svg class="t-arrow" width="44" height="12" aria-hidden="true"><use href="#i-arrow"/></svg>
          <div class="ticket-port arr">
            <div class="code">MJX</div>
            <div class="city">Miraj Central</div>
          </div>
